SET NAMES utf8mb4; USE muscu;
INSERT INTO motivational_messages(id,message) VALUES
(1,'Small progress is still progress.'),(2,'One more session, one more step forward.'),(3,'Consistency builds strength.'),(4,'Today’s work becomes tomorrow’s progress.'),(5,'Keep the standard high.'),(6,'Train, record, improve.'),(7,'The numbers will follow the work.'),(8,'The work compounds.'),(9,'Strong habits make strong results.'),(10,'Show up and do the work.'),(11,'Progress rewards patience.'),(12,'Another session, another reference point.'),(13,'Build the habit. Strength will follow.'),(14,'Good training is repeatable training.'),(15,'Leave the numbers better than you found them.'),(16,'The next set is the only set that matters.'),(17,'Calm work creates lasting progress.'),(18,'Keep moving in the right direction.'),(19,'A solid session is enough.'),(20,'Practice consistency, not perfection.'),(21,'Every recorded set teaches you something.'),(22,'Strength is built one session at a time.'),(23,'Stay patient and keep the signal clear.'),(24,'Do the work you can repeat.'),(25,'A steady pace still moves forward.'),(26,'The routine is doing its job.'),(27,'Make today useful.'),(28,'Good form. Clear numbers. Consistent work.'),(29,'Progress does not need to be dramatic.'),(30,'Keep building the evidence.'),(31,'Your history is becoming your advantage.'),(32,'One clean session can change the trend.'),(33,'Repeat the basics well.'),(34,'Strong days begin with showing up.'),(35,'The plan works when you work the plan.'),(36,'Keep the next goal close.'),(37,'Trust the process you can measure.'),(38,'Quality sets create quality progress.'),(39,'Train with intent, not urgency.'),(40,'Consistency makes the difficult familiar.'),(41,'A little stronger is still stronger.'),(42,'Stay focused on the next improvement.'),(43,'Your future numbers start here.'),(44,'Record the work. Respect the trend.'),(45,'The standard is simple: keep going.'),(46,'A calm session can be a great session.'),(47,'Effort becomes useful when it is consistent.'),(48,'The best program is the one you complete.'),(49,'Progress is built before it is visible.'),(50,'Finish today with a useful reference point.')
ON DUPLICATE KEY UPDATE message=VALUES(message);

